"""Sparse-node IPv6 pipeline compiler and lookup engine.

Reads one JSON request per line on stdin, writes one JSON response per line on
stdout.  Supports the "compile" and "lookup" operations described in the task
statement.  All arithmetic on bit budgets and utilisation ratios is exact
integer arithmetic.
"""
import json
import math
import sys

MASK128 = (1 << 128) - 1
MASK64 = 0xFFFFFFFFFFFFFFFF

INVALID_RESP = b'{"status":"invalid"}\n'
INFEASIBLE_RESP = b'{"status":"infeasible"}\n'

MAX_VALUES = 2000000
MAX_DEPTH = 64

# ---------------------------------------------------------------- exceptions


class Invalid(Exception):
    pass


# ---------------------------------------------------------------- type checks


def is_int(x):
    return x.__class__ is int


def is_str(x):
    return x.__class__ is str


def is_list(x):
    return x.__class__ is list


def is_dict(x):
    return x.__class__ is dict


# ---------------------------------------------------------------- ipv6 text

_HEX = frozenset('0123456789abcdefABCDEF')
_ALLOWED = frozenset('0123456789abcdefABCDEF:')
_DEC = frozenset('0123456789')

_parse_cache = {}


def parse_ipv6(s):
    """Strict colon separated hexadecimal notation.  Returns int or None."""
    if not is_str(s):
        return None
    r = _parse_cache.get(s)
    if r is not None:
        return r[0] if r[0] is not None else None
    v = _parse_ipv6(s)
    if len(_parse_cache) < 400000:
        _parse_cache[s] = (v,)
    return v


def _parse_ipv6(s):
    n = len(s)
    if n == 0 or n > 39:
        return None
    for ch in s:
        if ch not in _ALLOWED:
            return None
    i = s.find('::')
    if i >= 0:
        if s.find('::', i + 1) >= 0:
            return None
        head = s[:i]
        tail = s[i + 2:]
        left = head.split(':') if head else []
        right = tail.split(':') if tail else []
        cnt = len(left) + len(right)
        if cnt > 7:
            return None
        for g in left:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        for g in right:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        groups = left + ['0'] * (8 - cnt) + right
    else:
        groups = s.split(':')
        if len(groups) != 8:
            return None
        for g in groups:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
    v = 0
    for g in groups:
        v = (v << 16) | int(g, 16)
    return v


_canon_cache = {}


def canon_addr(a):
    """Canonical pure hexadecimal text form of a 128 bit address."""
    r = _canon_cache.get(a)
    if r is not None:
        return r
    g0 = (a >> 112) & 0xFFFF
    g1 = (a >> 96) & 0xFFFF
    g2 = (a >> 80) & 0xFFFF
    g3 = (a >> 64) & 0xFFFF
    g4 = (a >> 48) & 0xFFFF
    g5 = (a >> 32) & 0xFFFF
    g6 = (a >> 16) & 0xFFFF
    g7 = a & 0xFFFF
    groups = (g0, g1, g2, g3, g4, g5, g6, g7)
    best_i = -1
    best_l = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i + 1
            while j < 8 and groups[j] == 0:
                j += 1
            if j - i > best_l:
                best_l = j - i
                best_i = i
            i = j
        else:
            i += 1
    if best_l >= 2:
        left = ':'.join(format(x, 'x') for x in groups[:best_i])
        right = ':'.join(format(x, 'x') for x in groups[best_i + best_l:])
        s = left + '::' + right
    else:
        s = ':'.join(format(x, 'x') for x in groups)
    if len(_canon_cache) < 400000:
        _canon_cache[a] = s
    return s


def canon_prefix(a, length):
    return canon_addr(a) + '/' + str(length)


def parse_prefix(s):
    """Parse '<ipv6>/<len>'; returns (addr, length) or None."""
    if not is_str(s):
        return None
    i = s.find('/')
    if i < 0 or s.find('/', i + 1) >= 0:
        return None
    ls = s[i + 1:]
    ln = len(ls)
    if ln == 0 or ln > 3:
        return None
    if ls == '0':
        length = 0
    else:
        if ls[0] not in '123456789':
            return None
        for ch in ls[1:]:
            if ch not in _DEC:
                return None
        length = int(ls)
        if length > 128:
            return None
    a = parse_ipv6(s[:i])
    if a is None:
        return None
    if a & TMASK[length]:
        return None
    return (a, length)


# truncation masks: TMASK[d] keeps the top d bits
TMASK = [0] * 129
for _d in range(129):
    TMASK[_d] = MASK128 if _d == 0 else (MASK128 ^ ((1 << (128 - _d)) - 1))
TMASK[0] = 0


def trunc(a, d):
    return a & TMASK[d]


def align_up(x, k):
    r = x % k
    return x + (k - r) if r else x


def align8(x):
    return (x + 7) >> 3 << 3


def align64(x):
    return (x + 63) >> 6 << 6


# ---------------------------------------------------------------- json input


def _reject_float(s):
    raise Invalid('float')


def _reject_const(s):
    raise Invalid('constant')


def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid('duplicate key')
        d[k] = v
    return d


class Fallback(Exception):
    pass


_ACCEL = None


def prescan(data):
    """Cheap structural pre-check so hostile lines cannot exhaust memory."""
    global _ACCEL
    if _ACCEL is not None:
        r = _ACCEL.prescan_ok(data, MAX_VALUES, MAX_DEPTH)
        if r is True:
            return
        if r is False:
            raise Invalid('too large')
    # python fallback: crude but C-speed byte counting
    if len(data) > 1 << 20:
        c = (data.count(b'{') + data.count(b'[') + data.count(b'"') +
             data.count(b':') + data.count(b','))
        if c > 4000000:
            raise Invalid('too large')


def parse_request(data):
    prescan(data)
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('utf8')
    return json.loads(text, parse_float=_reject_float,
                      parse_constant=_reject_const,
                      object_pairs_hook=_pairs_hook)


# ---------------------------------------------------------------- layout


def build_layout(fib, cuts):
    """Canonical node layout.  fib: list of (addr, length, hop).

    Returns (stages, used) where stages[i] is a list of
    (node_addr, tuple_of_rules, tuple_of_edges); a rule is (addr, len, hop)
    sorted by (len, addr) and an edge is (addr, child_index) sorted by addr.
    """
    S = len(cuts) - 1
    fs = sorted(fib, key=lambda p: (p[0], p[1]))
    zero_rule = None
    for p in fs:
        if p[1] == 0:
            zero_rule = p
            break
    node_lists = []
    for i in range(S + 1):
        d = cuts[i]
        if i == 0:
            node_lists.append([0])
            continue
        lst = []
        if d < 128:
            m = TMASK[d]
            prev = None
            for p in fs:
                if p[1] <= d:
                    continue
                k = p[0] & m
                if k != prev:
                    lst.append(k)
                    prev = k
        node_lists.append(lst)
    stages = []
    used = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        nl = node_lists[i]
        nmap = {}
        ew = 0
        if e < 128:
            nmap = {v: j for j, v in enumerate(node_lists[i + 1])}
            ew = 32 + align8(e - b)
        mb = TMASK[b]
        me = TMASK[e]
        groups = []
        prevk = None
        for p in fs:
            if p[1] <= b:
                continue
            k = p[0] & mb
            if k != prevk:
                groups.append((k, [p]))
                prevk = k
            else:
                groups[-1][1].append(p)
        nodes = []
        tot = 0
        for j in range(len(nl)):
            na = nl[j]
            grp = groups[j][1] if j < len(groups) else ()
            rules = []
            cost = 128
            edges = []
            prevk = None
            for p in grp:
                l = p[1]
                if l <= e:
                    rules.append(p)
                    cost += 32 + align8(l - b)
                elif e < 128:
                    k = p[0] & me
                    if k != prevk:
                        edges.append((k, nmap[k]))
                        prevk = k
                        cost += ew
            if i == 0 and zero_rule is not None:
                rules.append(zero_rule)
                cost += 32
            if len(rules) > 1:
                rules.sort(key=lambda p: (p[1], p[0]))
            nodes.append((na, tuple(rules), tuple(edges)))
            tot += align64(cost)
        stages.append(nodes)
        used.append(tot)
    return stages, used


def peak_of(used, caps):
    bn, bd = 0, 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn, bd = u, c
    g = math.gcd(bn, bd)
    if g == 0:
        g = 1
    return bn // g, bd // g


def image_to_json(caps, ms, cuts, stages, used, peak):
    out_stages = []
    S = len(cuts) - 1
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        nodes = []
        for (na, rules, edges) in stages[i]:
            nodes.append({
                'prefix': canon_prefix(na, b),
                'rules': [{'prefix': canon_prefix(a, l), 'hop': h}
                          for (a, l, h) in rules],
                'edges': [{'prefix': canon_prefix(a, e), 'child': c}
                          for (a, c) in edges],
            })
        out_stages.append({'nodes': nodes})
    return {
        'status': 'ok',
        'capacities': list(caps),
        'max_stride': ms,
        'cuts': list(cuts),
        'stages': out_stages,
        'used_bits': list(used),
        'peak': {'num': peak[0], 'den': peak[1]},
    }


# ---------------------------------------------------------------- optimiser


def rat_less(a, b):
    return a[0] * b[1] < b[0] * a[1]


def py_find_cuts(fib, caps, S, ms):
    """Pure python reference optimiser.  Returns (cuts, used, peak) or None."""
    fs = sorted(fib, key=lambda p: (p[0], p[1]))
    has_zero = bool(fs) and fs[0][1] == 0
    by_len = [[] for _ in range(129)]
    for p in fs:
        by_len[p[1]].append(p[0])
    ncache = {}

    def node_list(d):
        r = ncache.get(d)
        if r is None:
            if d == 0:
                r = [0]
            elif d >= 128:
                r = []
            else:
                lst = []
                m = TMASK[d]
                prev = None
                for p in fs:
                    if p[1] <= d:
                        continue
                    k = p[0] & m
                    if k != prev:
                        lst.append(k)
                        prev = k
                r = lst
            ncache[d] = r
        return r

    U = [None] * 129
    for b in range(128):
        row = [-1] * 129
        nb = node_list(b)
        cb = len(nb)
        emax = b + ms
        if emax > 128:
            emax = 128
        if cb == 0:
            for e in range(b + 1, emax + 1):
                row[e] = 0
            U[b] = row
            continue
        racc = [0] * cb
        if b == 0 and has_zero:
            racc[0] += 32
        for e in range(b + 1, emax + 1):
            w = 32 + align8(e - b)
            m = TMASK[b]
            for a in by_len[e]:
                k = a & m
                lo = 0
                hi = cb - 1
                while lo <= hi:
                    mid = (lo + hi) >> 1
                    if nb[mid] == k:
                        racc[mid] += w
                        break
                    if nb[mid] < k:
                        lo = mid + 1
                    else:
                        hi = mid - 1
            ecnt = [0] * cb
            if e < 128:
                ne = node_list(e)
                me = TMASK[b]
                k = 0
                j = 0
                le = len(ne)
                while k < cb and j < le:
                    par = ne[j] & me
                    if par == nb[k]:
                        ecnt[k] += 1
                        j += 1
                    elif par > nb[k]:
                        k += 1
                    else:
                        j += 1
            ew = w if e < 128 else 0
            tot = 0
            for k in range(cb):
                tot += align64(128 + racc[k] + ecnt[k] * ew)
            row[e] = tot
        U[b] = row

    f = [[None] * 129 for _ in range(S + 1)]
    f[S][128] = (0, 1)
    for i in range(S - 1, -1, -1):
        fi = f[i]
        fn = f[i + 1]
        cap = caps[i]
        Ui = U
        for d in range(128):
            best = None
            emax = d + ms
            if emax > 128:
                emax = 128
            row = Ui[d]
            for e in range(d + 1, emax + 1):
                nxt = fn[e]
                if nxt is None:
                    continue
                u = row[e]
                if u < 0:
                    continue
                cand = (u, cap)
                if rat_less(cand, nxt):
                    cand = nxt
                if best is None or rat_less(cand, best):
                    best = cand
            fi[d] = best
    top = f[0][0]
    if top is None or top[0] > top[1]:
        return None
    cuts = [0]
    d = 0
    used = []
    for i in range(S):
        emax = d + ms
        if emax > 128:
            emax = 128
        tgt = f[i][d]
        chosen = -1
        for e in range(d + 1, emax + 1):
            nxt = f[i + 1][e]
            if nxt is None:
                continue
            u = U[d][e]
            if u < 0:
                continue
            cand = (u, caps[i])
            if rat_less(cand, nxt):
                cand = nxt
            if cand[0] == tgt[0] and cand[1] == tgt[1]:
                chosen = e
                break
        if chosen < 0:
            return None
        cuts.append(chosen)
        used.append(U[d][chosen])
        d = chosen
    return cuts, used, peak_of(used, caps)


def find_placement(fib, caps, S, ms):
    """Returns (cuts, used, peak) for an optimal feasible placement or None."""
    res = None
    if _ACCEL is not None and _ACCEL.available:
        try:
            rc, cuts, used_c, num, den = _ACCEL.find_cuts(
                [(a, l) for (a, l, h) in fib], caps, S, ms)
        except Exception:
            rc = -1
            cuts = None
        if rc == 1:
            res = None
            # cross-check with python when the native path claims infeasible
            if _CROSS_CHECK:
                res = py_find_cuts(fib, caps, S, ms)
                if res is not None:
                    return res
            return None
        if rc == 0 and cuts is not None:
            stages, used = build_layout(fib, cuts)
            if used == used_c and (num, den) == peak_of(used, caps):
                peak = (num, den)
                if peak[0] <= peak[1]:
                    return cuts, used, peak
            # disagreement: fall through to the python optimiser
            if _CROSS_CHECK:
                sys.stderr.write('accel/python disagreement\n')
            res = py_find_cuts(fib, caps, S, ms)
            return res
    return py_find_cuts(fib, caps, S, ms)


_CROSS_CHECK = False

# ---------------------------------------------------------------- compile


def do_compile(obj):
    if set(obj.keys()) != {'op', 'fib', 'capacities', 'max_stride'}:
        raise Invalid('keys')
    fib_raw = obj['fib']
    caps = obj['capacities']
    ms = obj['max_stride']
    if not is_list(fib_raw) or not (0 <= len(fib_raw) <= 2048):
        raise Invalid('fib')
    if not is_list(caps) or not (4 <= len(caps) <= 16):
        raise Invalid('caps')
    for c in caps:
        if not is_int(c) or c < 1 or c > 1000000000:
            raise Invalid('cap')
    if not is_int(ms) or ms < 1 or ms > 32:
        raise Invalid('ms')
    fib = []
    seen = set()
    for rec in fib_raw:
        if not is_dict(rec) or set(rec.keys()) != {'prefix', 'hop'}:
            raise Invalid('rec')
        p = rec['prefix']
        h = rec['hop']
        if not is_str(p):
            raise Invalid('prefix')
        if not is_int(h) or h < 0 or h > 65535:
            raise Invalid('hop')
        pr = parse_prefix(p)
        if pr is None:
            raise Invalid('prefix value')
        if pr in seen:
            raise Invalid('dup prefix')
        seen.add(pr)
        fib.append((pr[0], pr[1], h))
    S = len(caps)
    place = find_placement(fib, caps, S, ms)
    if place is None:
        return 'infeasible'
    cuts, used, peak = place
    stages, used2 = build_layout(fib, cuts)
    if used2 != used:
        used = used2
        peak = peak_of(used, caps)
        if peak[0] > peak[1]:
            return 'infeasible'
    return image_to_json(caps, ms, cuts, stages, used, peak)


# ---------------------------------------------------------------- image check


def validate_image(img):
    """Fully re-derive and check an image.  Returns (fib, cuts, caps, ms, S)."""
    if not is_dict(img):
        raise Invalid('image')
    if set(img.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                           'stages', 'used_bits', 'peak'}:
        raise Invalid('image keys')
    if img['status'] != 'ok':
        raise Invalid('status')
    caps = img['capacities']
    if not is_list(caps) or not (4 <= len(caps) <= 16):
        raise Invalid('caps')
    for c in caps:
        if not is_int(c) or c < 1 or c > 1000000000:
            raise Invalid('cap')
    S = len(caps)
    ms = img['max_stride']
    if not is_int(ms) or ms < 1 or ms > 32:
        raise Invalid('ms')
    cuts = img['cuts']
    if not is_list(cuts) or len(cuts) != S + 1:
        raise Invalid('cuts')
    for c in cuts:
        if not is_int(c) or c < 0 or c > 128:
            raise Invalid('cut value')
    if cuts[0] != 0 or cuts[S] != 128:
        raise Invalid('cut ends')
    for i in range(S):
        st = cuts[i + 1] - cuts[i]
        if st < 1 or st > ms:
            raise Invalid('stride')
    ub = img['used_bits']
    if not is_list(ub) or len(ub) != S:
        raise Invalid('used_bits')
    for u in ub:
        if not is_int(u) or u < 0:
            raise Invalid('used value')
    pk = img['peak']
    if not is_dict(pk) or set(pk.keys()) != {'num', 'den'}:
        raise Invalid('peak')
    pn = pk['num']
    pd = pk['den']
    if not is_int(pn) or not is_int(pd) or pn < 0 or pd <= 0:
        raise Invalid('peak value')
    stages_raw = img['stages']
    if not is_list(stages_raw) or len(stages_raw) != S:
        raise Invalid('stages')

    fib = []
    parsed = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        st = stages_raw[i]
        if not is_dict(st) or set(st.keys()) != {'nodes'}:
            raise Invalid('stage')
        nl = st['nodes']
        if not is_list(nl):
            raise Invalid('nodes')
        stage_nodes = []
        prev_node = None
        for nd in nl:
            if not is_dict(nd) or set(nd.keys()) != {'prefix', 'rules', 'edges'}:
                raise Invalid('node')
            pv = nd['prefix']
            pr = parse_prefix(pv)
            if pr is None:
                raise Invalid('node prefix')
            if pr[1] != b or canon_prefix(pr[0], b) != pv:
                raise Invalid('node prefix form')
            na = pr[0]
            if prev_node is not None and na <= prev_node:
                raise Invalid('node order')
            prev_node = na
            if na & TMASK[b]:
                raise Invalid('node host bits')
            rules_raw = nd['rules']
            if not is_list(rules_raw):
                raise Invalid('rules')
            rules = []
            prev_key = None
            for r in rules_raw:
                if not is_dict(r) or set(r.keys()) != {'prefix', 'hop'}:
                    raise Invalid('rule')
                h = r['hop']
                if not is_int(h) or h < 0 or h > 65535:
                    raise Invalid('hop')
                rp = r['prefix']
                pr2 = parse_prefix(rp)
                if pr2 is None:
                    raise Invalid('rule prefix')
                if canon_prefix(pr2[0], pr2[1]) != rp:
                    raise Invalid('rule prefix form')
                a, l = pr2
                if l == 0:
                    if not (i == 0 and b == 0 and na == 0):
                        raise Invalid('zero rule placement')
                elif not (b < l <= e):
                    raise Invalid('rule depth')
                if (a & TMASK[b]) != na:
                    raise Invalid('rule under node')
                key = (l, a)
                if prev_key is not None and key <= prev_key:
                    raise Invalid('rule order')
                prev_key = key
                rules.append((a, l, h))
                fib.append((a, l, h))
            edges_raw = nd['edges']
            if not is_list(edges_raw):
                raise Invalid('edges')
            if e == 128 and len(edges_raw) != 0:
                raise Invalid('edges at 128')
            edges = []
            prev_e = None
            for ed in edges_raw:
                if not is_dict(ed) or set(ed.keys()) != {'prefix', 'child'}:
                    raise Invalid('edge')
                ch = ed['child']
                if not is_int(ch):
                    raise Invalid('child')
                ep = ed['prefix']
                pr3 = parse_prefix(ep)
                if pr3 is None:
                    raise Invalid('edge prefix')
                if pr3[1] != e or canon_prefix(pr3[0], e) != ep:
                    raise Invalid('edge prefix form')
                a = pr3[0]
                if prev_e is not None and a <= prev_e:
                    raise Invalid('edge order')
                prev_e = a
                edges.append((a, ch))
            stage_nodes.append((na, tuple(rules), tuple(edges)))
        parsed.append(stage_nodes)

    if len(fib) > 2048:
        raise Invalid('fib size')
    seen = set()
    for (a, l, h) in fib:
        k = (a, l)
        if k in seen:
            raise Invalid('dup route')
        seen.add(k)
    for i in range(S - 1):
        e = cuts[i + 1]
        if e == 128:
            continue
        nn = len(parsed[i + 1])
        for (na, rules, edges) in parsed[i]:
            for (ea, ch) in edges:
                if ch < 0 or ch >= nn:
                    raise Invalid('child range')
                if parsed[i + 1][ch][0] != ea:
                    raise Invalid('child target')
    expected, used = build_layout(fib, cuts)
    for i in range(S):
        exp = expected[i]
        got = parsed[i]
        if len(exp) != len(got):
            raise Invalid('node count')
        for j in range(len(exp)):
            if exp[j] != got[j]:
                raise Invalid('node content')
    if len(ub) != len(used):
        raise Invalid('used len')
    for i in range(S):
        if ub[i] != used[i]:
            raise Invalid('used value mismatch')
        if used[i] > caps[i]:
            raise Invalid('capacity')
    num, den = peak_of(used, caps)
    if pn != num or pd != den:
        raise Invalid('peak mismatch')
    if num > den:
        raise Invalid('peak over')
    return fib, cuts, caps, ms, S


# ---------------------------------------------------------------- lookup


def py_lpm(rules, queries):
    by_len = {}
    for (a, l, h) in rules:
        d = by_len.get(l)
        if d is None:
            d = {}
            by_len[l] = d
        d[a] = h
    lengths = sorted(by_len.keys(), reverse=True)
    masks = [(l, TMASK[l]) for l in lengths]
    dicts = [by_len[l] for l in lengths]
    out = []
    for q in queries:
        res = None
        for k in range(len(lengths)):
            h = dicts[k].get(q & masks[k][1])
            if h is not None:
                res = (h, lengths[k])
                break
        out.append(res)
    return out


def do_lookup(obj):
    if set(obj.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid('keys')
    addrs_raw = obj['addresses']
    if not is_list(addrs_raw) or len(addrs_raw) > 20000:
        raise Invalid('addresses')
    fib, cuts, caps, ms, S = validate_image(obj['image'])
    queries = []
    for s in addrs_raw:
        a = parse_ipv6(s)
        if a is None:
            raise Invalid('address')
        queries.append(a)
    rules = [(a, l, h) for (a, l, h) in fib]
    res = None
    if _ACCEL is not None and _ACCEL.available and (rules or queries):
        try:
            res = _ACCEL.lpm_batch(rules, queries)
        except Exception:
            res = None
    if res is None:
        res = py_lpm(rules, queries)
    answers = []
    for (h, l) in res:
        if h < 0:
            answers.append({'hop': None, 'prefix_length': None})
        else:
            answers.append({'hop': h, 'prefix_length': l})
    return {'status': 'ok', 'answers': answers}


# ---------------------------------------------------------------- driver


def handle_line(line):
    try:
        if not line:
            return INVALID_RESP
        obj = parse_request(line)
        if not is_dict(obj):
            return INVALID_RESP
        op = obj.get('op')
        if op == 'compile':
            r = do_compile(obj)
        elif op == 'lookup':
            r = do_lookup(obj)
        else:
            return INVALID_RESP
        if r == 'infeasible':
            return INFEASIBLE_RESP
        return (json.dumps(r, separators=(',', ':'), ensure_ascii=True)
                .encode('ascii') + b'\n')
    except Invalid:
        return INVALID_RESP
    except Exception:
        return INVALID_RESP


def main(src_dir=None):
    global _ACCEL, _CROSS_CHECK
    import os
    if os.environ.get('SCAMP_NO_ACCEL') == '1':
        _ACCEL = None
    else:
        try:
            import scamp_accel
            if src_dir is None:
                src_dir = os.path.dirname(os.path.abspath(__file__))
            _ACCEL = scamp_accel.Accel(src_dir)
        except Exception:
            _ACCEL = None
    if os.environ.get('SCAMP_CROSS_CHECK') == '1':
        _CROSS_CHECK = True
    out = sys.stdout.buffer
    inp = sys.stdin.buffer
    while True:
        try:
            line = inp.readline()
        except Exception:
            break
        if not line:
            break
        if line.endswith(b'\n'):
            line = line[:-1]
        if line.endswith(b'\r'):
            line = line[:-1]
        try:
            resp = handle_line(line)
        except BaseException:
            resp = INVALID_RESP
        try:
            out.write(resp)
            out.flush()
        except Exception:
            break
    try:
        out.flush()
    except Exception:
        pass
